def tri(n):
    memo = {1: 3}

    def calculate(k):
        if k in memo:
            return memo[k]
        if k % 2 == 0:
            result = 1 + k / 2
        else:
            result = calculate(k - 1) + calculate(k - 2) + calculate(k + 1)
        memo[k] = result
        return result

    return [calculate(i) for i in range(1, n + 1)]
